package net.civeira.phylax.feature.observe.observedsource.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class OriginTypeVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property origin type of observed source ")
  void test_origin_type_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> OriginTypeVO.tryFrom(null));
    Assertions.assertEquals("one", OriginTypeVO.from("one").getOriginType());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> OriginTypeVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", OriginTypeVO.from("one").toString());
  }
}
